/// Build the decorator list for a given config: empty when `exit_gates` is
/// empty, otherwise a single `exit-gate` decorator that gates `message_user`
/// on the configured shell commands. Called at each handle_turn invocation.
fn exit_gate_decorators(config: &AgentConfig) -> Vec<ToolDecorator> {
    if config.exit_gates.is_empty() {
        Vec::new()
    } else {
        vec![exit_gate(config.exit_gates.clone())]
    }
}

static FILE_PROMPT_SPLIT_REGEX: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(?m)^---$").unwrap());
pub(crate) fn parse_file_prompts(content: &str) -> Vec<String> {
    FILE_PROMPT_SPLIT_REGEX
        .split(content)
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

fn prepend_input_files(user_content: &str, config: &AgentConfig) -> String {
    if config.input_files.is_empty() {
        return user_content.to_string();
    }

    fn glob_matches(pattern: &str, file_name: &str) -> bool {
        let escaped = pattern
            .chars()
            .map(|ch| {
                if ch == '*' {
                    ".*".to_string()
                } else {
                    regex::escape(&ch.to_string())
                }
            })
            .collect::<String>();
        Regex::new(&format!("^{escaped}$"))
            .map(|re| re.is_match(file_name))
            .unwrap_or(false)
    }

    let mut sections = Vec::new();
    for file_pat in &config.input_files {
        let resolved = if file_pat.is_absolute() {
            file_pat.clone()
        } else {
            config.work_dir.join(file_pat)
        };

        let dir = resolved
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| PathBuf::from("."));
        let base = resolved
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_default();

        let files = if base.contains('*') {
            if !dir.is_dir() {
                Vec::new()
            } else {
                let mut expanded = fs::read_dir(&dir)
                    .ok()
                    .into_iter()
                    .flatten()
                    .filter_map(|entry| entry.ok())
                    .map(|entry| entry.path())
                    .filter(|path| {
                        path.file_name()
                            .map(|name| glob_matches(&base, &name.to_string_lossy()))
                            .unwrap_or(false)
                    })
                    .collect::<Vec<_>>();
                expanded.sort();
                expanded
            }
        } else {
            vec![resolved]
        };

        for file_path in files {
            if file_path.is_file() {
                if let Ok(content) = fs::read_to_string(&file_path) {
                    let file_name = file_path
                        .file_name()
                        .map(|name| name.to_string_lossy().into_owned())
                        .unwrap_or_else(|| file_path.to_string_lossy().into_owned());
                    sections.push(format!("--- {} ---\n{}", file_name, content));
                }
            }
        }
    }

    if sections.is_empty() {
        user_content.to_string()
    } else {
        format!("{}\n\n{}", sections.join("\n\n"), user_content)
    }
}

fn write_output_file(config: &AgentConfig, content: &str) -> Result<()> {
    if let Some(path) = &config.output_file {
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent)?;
            }
        }
        fs::write(path, format!("{}\n", content))?;
    }
    Ok(())
}

pub(crate) fn is_interactive_eof(error: &ReadlineError) -> bool {
    matches!(error, ReadlineError::Eof)
        || matches!(error, ReadlineError::Io(io_error) if matches!(io_error.kind(), ErrorKind::UnexpectedEof | ErrorKind::BrokenPipe))
}
#[derive(Debug, PartialEq, Eq)]
pub(crate) enum CommandResult {
    Quit,
    Compact { summary: String },
    Custom { response: String },
    Unknown { name: String },
}

pub(crate) fn is_command(input: &str) -> bool {
    input.starts_with('/')
}

fn load_compaction_prompt() -> String {
    // Rust-idiomatic source-relative resolution for shared prompt assets.
    let template_path = if let Ok(manifest_dir) = env::var("CARGO_MANIFEST_DIR") {
        std::path::PathBuf::from(manifest_dir).join("../compaction-prompt.txt")
    } else {
        std::path::PathBuf::from("../compaction-prompt.txt")
    };

    fs::read_to_string(&template_path).expect("Failed to read compaction prompt template")
}

pub(crate) async fn handle_command(
    input: &str,
    provider: &dyn ChatProvider,
    conversation: &Conversation,
    agent_config: &AgentConfig,
    session_id: &str,
) -> Result<CommandResult> {
    let command_name = input
        .trim_start_matches('/')
        .split_whitespace()
        .next()
        .unwrap_or_default();

    match command_name {
        "quit" | "exit" => Ok(CommandResult::Quit),
        "compact" => {
            let compacted = format_conversation_for_compaction(conversation);
            // Module 02 scaffolding: session-aware compaction prompt
            let past_summaries = load_past_session_summaries(
                agent_config.history_dir.as_deref().unwrap_or(Path::new("")),
                session_id,
                provider,
            )
            .await;
            let past_section = if past_summaries.is_empty() {
                String::new()
            } else {
                format!("Previous sessions:\n{}\n\n", past_summaries)
            };
            let prompt = load_compaction_prompt()
                .replace("{{CONVERSATION}}", &compacted)
                .replace("{{PAST_SESSIONS}}", &past_section);

            let prompt_message: ChatCompletionRequestMessage =
                ChatCompletionRequestUserMessageArgs::default()
                    .content(prompt)
                    .build()?
                    .into();

            let summary = provider.complete(&[prompt_message]).await?;
            Ok(CommandResult::Compact { summary })
        }
        other => {
            // Module 02 scaffolding: custom command dispatch
            let commands = discover_commands(agent_config.commands_dir.as_deref());
            if let Some(cmd) = commands.iter().find(|c| c.name == other) {
                let args = input
                    .trim_start_matches('/')
                    .trim()
                    .strip_prefix(other)
                    .unwrap_or("")
                    .trim();
                let prompt = execute_command(cmd, args);
                let msg = ChatCompletionRequestUserMessageArgs::default()
                    .content(prompt)
                    .build()?
                    .into();
                let response = provider.complete(&[msg]).await?;
                Ok(CommandResult::Custom { response })
            } else {
                Ok(CommandResult::Unknown {
                    name: other.to_string(),
                })
            }
        }
    }
}

